select cellar.merge_product('20d070d3-2c56-4c85-9dbb-8e174f9f4b5a'::uuid, 'fad1cb11-5352-44c3-87fe-37e4b1f1a175'::uuid, '2018');  -- Country Cask Strength -> Cask Strength Bourbon
select cellar.merge_product('dc32d33e-ddf2-4672-af36-a7e47e1f978b'::uuid, 'e9f85bda-d95b-4976-b49a-4258820f3cf2'::uuid, '2017');  -- N Rye -> Straight Rye
select cellar.merge_product('72351c22-b503-4726-8785-105764aea399'::uuid, 'e9f85bda-d95b-4976-b49a-4258820f3cf2'::uuid, '2020');  -- Rye'd On -> Straight Rye
update cellar.makers set website = coalesce(website, 'https://pinhookbourbon.com'), country = coalesce(country, 'US'), updated_at = now() where id = 'c97e82de-a08b-41c5-80eb-b5e95075f50e';
